<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick,defineAsyncComponent} from 'vue'
import {MessageCircle,Send,RefreshCw,Settings2,ArrowLeft,Search,Check,CheckCheck,UserRound,ChevronDown} from 'lucide-vue-next'
import {voiceApi,stamp} from '../voice/operations'

const SocialLeadsPanel=defineAsyncComponent(()=>import('./SocialLeadsPanel.vue'))
const leadPanel=ref(null),messageList=ref(null)
const state=ref(null),detail=ref(null),error=ref(''),notice=ref(''),busy=ref(false),search=ref(''),status=ref('open'),selectedSender=ref(''),page=ref(1),messagePage=ref(1),body=ref(''),template=ref(''),experimental=ref(false),settings=ref(false),route=ref({sender_id:'',queue_id:'',enabled:false,max_open:5,apply_pending:false}),assignee=ref(''),queue=ref('')
let timer=null,polling=false,sendKey=null,disposed=false

const totals=computed(()=>(state.value?.senders||[]).reduce((a,s)=>({total:a.total+(s.counts?.total||0),unread:a.unread+(s.counts?.unread||0)}),{total:0,unread:0}))
const messages=computed(()=>[...(detail.value?.messages.data||[])].reverse())
const canReply=computed(()=>detail.value?.conversation.assigned_user_id===state.value?.user_id&&detail.value?.conversation.status==='open')
const sender=id=>state.value?.senders.find(s=>s.id===id)
const person=id=>state.value?.agents.find(s=>s.id===id)?.name||'Sem responsável'
const labels={received:'Recebida',sending:'Enviando',accepted:'Aceita',queued:'Na fila',sent:'Enviada',delivered:'Entregue',read:'Lida',unknown:'Sem confirmação',failed:'Falhou',undelivered:'Não entregue',cancelled:'Cancelada'}
const initials=value=>(value||'?').trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()
const displayName=c=>c.contact_name||c.phone
const unread=c=>c.last_inbound_at&&(!c.read_at||c.last_inbound_at>c.read_at)
const preview=c=>(c.last_message_direction==='outbound'?'Você: ':'')+(c.last_message_preview||'Mensagem')
const buttons=m=>{try{return JSON.parse(m.interactive||'{}').buttons||[]}catch{return []}}
const statusIcon=m=>m.direction==='outbound'&&['delivered','read'].includes(m.status)?CheckCheck:Check

async function api(path='',method='GET',data){return voiceApi('/conversations'+path,method,data)}
async function load(){state.value=await api('?'+new URLSearchParams({status:status.value,sender_id:selectedSender.value,search:search.value,page:page.value}))}
async function chooseSender(id){if(body.value||template.value){notice.value='Envie ou limpe o rascunho antes de trocar de número.';return}selectedSender.value=id;page.value=1;messagePage.value=1;detail.value=null;await load()}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function scrollBottom(){await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight}
async function open(c,scroll=true){detail.value=await api('/'+c.id+'?page='+messagePage.value);assignee.value=detail.value.conversation.assigned_user_id||'';queue.value=detail.value.conversation.queue_id||'';if(scroll)await scrollBottom()}
async function select(c){if(body.value||template.value){notice.value='Envie ou limpe o rascunho antes de abrir outra conversa.';return}messagePage.value=1;await open(c);await api('/'+c.id+'/read','POST',{});await load()}
async function assign(mine=false,nextStatus=null){const c=detail.value.conversation;await api('/'+c.id+'/assign','POST',{user_id:mine?state.value.user_id:(assignee.value||null),queue_id:queue.value||null,revision:c.revision,status:nextStatus||c.status});await open(c);await load()}
async function send(){const c=detail.value.conversation;sendKey ||= crypto.randomUUID();const data={idempotency_key:sendKey,body:template.value?null:body.value,qr_template_id:template.value||null,experimental_confirmed:experimental.value};const result=await api('/'+c.id+'/send','POST',data);sendKey=null;body.value='';template.value='';experimental.value=false;await open(c);await load();notice.value=result.status==='unknown'?'Envio sem confirmação. Consulte o histórico antes de tentar novamente.':'Mensagem registrada: '+(labels[result.status]||result.status)}
async function older(){messagePage.value++;await open(detail.value.conversation,false)}
async function tick(){if(busy.value||polling||disposed)return;polling=true;try{await load();if(detail.value){const id=detail.value.conversation.id;const previous=detail.value.messages.total;const fresh=await api('/'+id+'?page='+messagePage.value);if(detail.value?.conversation.id===id){detail.value=fresh;if(fresh.messages.total!==previous)await scrollBottom()}}}catch(e){error.value=e.message}finally{polling=false}}
onMounted(()=>{run(load);timer=setInterval(tick,5000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
defineExpose({requestLeave:fn=>{if(body.value||template.value){notice.value='Envie ou limpe o rascunho antes de sair.';return}if(leadPanel.value)leadPanel.value.requestLeave(fn);else fn()}})
</script>

<template>
<div class="inbox" :aria-busy="busy">
  <div class="heading">
    <div><span class="eyebrow">CONVERSAS</span><h1>Atendimento por WhatsApp</h1><p>Acompanhe respostas e continue cada atendimento em uma única tela.</p></div>
    <div class="actions"><button v-if="state?.can_configure" class="secondary" @click="settings=!settings"><Settings2 :size="16"/>Distribuição</button><button class="secondary" @click="run(async()=>{await load();if(detail)await open(detail.conversation)})"><RefreshCw :size="16"/>Atualizar</button></div>
  </div>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>

  <div v-if="settings&&state?.can_configure" class="table-card box"><h3>Números, filas e distribuição</h3><p>Vincule o número à equipe para que os agentes vejam as conversas da fila.</p><form @submit.prevent="run(async()=>{const result=await api('/routes','POST',route);await load();notice='Vínculo salvo. '+result.pending_linked+' conversa(s) pendente(s) vinculada(s).';route.apply_pending=false})"><div class="grid"><label>Remetente<select v-model.number="route.sender_id" required><option value="">Selecione</option><option v-for="s in state.senders" :key="s.id" :value="s.id">{{s.label}} · {{s.number}}</option></select></label><label>Fila<select v-model.number="route.queue_id" required><option value="">Selecione</option><option v-for="q in state.queues" :key="q.id" :value="q.id">{{q.name}}</option></select></label><label>Conversas abertas por atendente<input type="number" v-model.number="route.max_open" min="1" max="20"></label></div><label class="check-label"><input type="checkbox" v-model="route.enabled">Distribuir entre atendentes disponíveis</label><label class="check-label"><input type="checkbox" v-model="route.apply_pending">Incluir conversas abertas ainda sem fila e responsável</label><button class="primary" :disabled="busy">Salvar distribuição</button></form><p v-for="r in state.routes" :key="r.sender_id">{{sender(r.sender_id)?.number}} · {{state.queues.find(q=>q.id===r.queue_id)?.name}} · {{r.enabled?'Atribuição automática':'Agentes assumem manualmente'}} <button class="secondary" @click="route={...r,enabled:!!r.enabled,apply_pending:false}">Editar</button></p></div>

  <div class="chat-shell" :class="{selected:detail}">
    <aside class="thread-pane">
      <div class="thread-toolbar"><div><strong>Conversas</strong><small>{{totals.unread}} não lidas</small></div><button class="icon-button" title="Atualizar" @click="run(load)"><RefreshCw :size="18"/></button></div>
      <form class="thread-filters" @submit.prevent="run(async()=>{page=1;await load()})">
        <label class="search-box"><Search :size="17"/><input v-model="search" placeholder="Pesquisar telefone" aria-label="Pesquisar telefone"></label>
        <div class="filter-row"><label class="select-wrap"><select aria-label="Número de WhatsApp" v-model="selectedSender" @change="run(()=>chooseSender(selectedSender))"><option value="">Todos os números</option><option v-for="s in state?.senders||[]" :key="s.id" :value="s.id">{{s.label}}</option></select><ChevronDown :size="15"/></label><label class="select-wrap"><select aria-label="Estado das conversas" v-model="status" @change="page=1;run(load)"><option value="">Todas</option><option value="open">Abertas</option><option value="closed">Concluídas</option></select><ChevronDown :size="15"/></label></div>
      </form>
      <div class="thread-list">
        <button v-for="c in state?.rows.data||[]" :key="c.id" :disabled="busy" :class="['thread',{active:detail?.conversation.id===c.id,unread:unread(c)}]" @click="run(()=>select(c))">
          <span class="avatar">{{initials(displayName(c))}}</span><span class="thread-copy"><span class="thread-line"><strong>{{displayName(c)}}</strong><time>{{stamp(c.last_message_at)}}</time></span><span class="thread-line"><small class="preview">{{preview(c)}}</small><b v-if="unread(c)" class="unread-dot" aria-label="Não lida"></b></span><small class="owner">{{person(c.assigned_user_id)}}</small></span>
        </button>
        <p v-if="!state?.rows.data.length" class="empty">Nenhuma conversa neste filtro.</p>
      </div>
      <div class="pager"><button class="secondary" :disabled="page===1" @click="page--;run(load)">Anterior</button><span>{{page}} / {{state?.rows.last_page||1}}</span><button class="secondary" :disabled="page>=(state?.rows.last_page||1)" @click="page++;run(load)">Próxima</button></div>
    </aside>

    <article class="conversation-pane">
      <template v-if="detail">
        <header class="chat-header"><button class="icon-button mobile-back" @click="detail=null"><ArrowLeft :size="19"/></button><span class="avatar large">{{initials(detail.contact?.name||detail.conversation.phone)}}</span><div class="chat-identity"><h2>{{detail.contact?.name||detail.conversation.phone}}</h2><p>{{detail.conversation.phone}} · {{sender(detail.conversation.sender_id)?.label}} · {{person(detail.conversation.assigned_user_id)}}</p></div><div class="chat-actions"><button v-if="!detail.conversation.assigned_user_id||state.can_manage" class="secondary" @click="run(()=>assign(true))">Assumir</button><button v-if="canReply||state.can_manage" class="secondary" @click="run(()=>assign(false,detail.conversation.status==='open'?'closed':'open'))">{{detail.conversation.status==='open'?'Concluir':'Reabrir'}}</button></div></header>
        <div v-if="detail.ai||detail.contact?.suppressed_at" class="chat-alerts"><div v-if="detail.ai" class="notice"><strong>{{detail.ai.name}} · Agente de IA</strong><span>{{detail.ai.summary||detail.ai.reason||'Conversa em atendimento automático.'}}</span></div><p v-if="detail.contact?.suppressed_at" class="error">Contato pediu interrupção. Envios bloqueados.</p></div>
        <details v-if="state.can_manage" class="assignment"><summary>Responsável e fila</summary><div class="grid"><label>Fila<select v-model.number="queue"><option value="">Sem fila</option><option v-for="q in state.queues" :key="q.id" :value="q.id">{{q.name}}</option></select></label><label>Atendente<select v-model.number="assignee"><option value="">Sem responsável</option><option v-for="a in state.agents" :key="a.id" :value="a.id">{{a.name}}</option></select></label></div><button class="secondary" @click="run(()=>assign())">Salvar responsável</button></details>
        <div ref="messageList" class="messages">
          <button v-if="detail.messages.last_page>1&&messagePage<detail.messages.last_page" class="older" @click="run(older)">Carregar mensagens anteriores</button>
          <div v-for="m in messages" :key="m.id" :class="['bubble-row',m.direction]"><div class="bubble"><audio v-if="m.speech_asset_id" controls preload="none" :src="'/api/voice/conversations/'+detail.conversation.id+'/media/'+m.id"/><p v-if="m.body">{{m.body}}</p><p v-else class="muted">Conteúdo não textual</p><div v-if="buttons(m).length" class="button-list"><span v-for="b in buttons(m)" :key="b.id||b.label">{{b.label||b.title}}</span></div><strong v-if="m.button_label" class="chosen">{{m.button_label}}</strong><span class="bubble-meta"><time>{{stamp(m.created_at)}}</time><component :is="statusIcon(m)" v-if="m.direction==='outbound'" :size="15" :class="{read:m.status==='read'}"/><span class="sr-only">{{labels[m.status]||m.status}}</span></span></div></div>
        </div>
        <form v-if="canReply" class="composer" @submit.prevent="run(send)"><label v-if="sender(detail.conversation.sender_id)?.provider==='qr'" class="template-select">Template com botões<select v-model="template" @change="sendKey=null"><option value="">Texto livre</option><option v-for="t in state.templates" :key="t.id" :value="t.id">{{t.name}} · experimental</option></select></label><div v-if="!template" class="compose-row"><textarea v-model="body" @input="sendKey=null" required maxlength="4000" rows="1" placeholder="Digite uma mensagem" aria-label="Mensagem"></textarea><button class="send-button" :disabled="busy||!body" aria-label="Enviar mensagem"><Send :size="20"/></button></div><template v-else><p>{{state.templates.find(t=>t.id===template)?.body}}</p><label class="check-label"><input type="checkbox" v-model="experimental" required>Confirmo o envio experimental dos botões por QR</label><button class="primary" :disabled="busy"><Send :size="16"/>Enviar resposta</button></template><small>Disponível por 24 horas após a mensagem do cliente.</small></form>
        <div v-else class="composer locked"><UserRound :size="18"/><span>Assuma a conversa aberta para responder.</span></div>
      </template>
      <div v-else class="placeholder"><MessageCircle :size="56"/><h2>DiscAI Conversas</h2><p>Selecione uma conversa para ver o histórico completo e responder ao cliente.</p></div>
    </article>
  </div>
  <SocialLeadsPanel v-if="state?.can_manage" ref="leadPanel"/>
</div>
</template>

<style scoped>
.inbox{min-width:0}.heading,.actions,.chat-actions{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.heading{margin-bottom:18px}.heading h1{margin:.2rem 0;font-size:clamp(1.6rem,3vw,2.2rem)}.heading p,.inbox small,.inbox p{color:#75806b;line-height:1.55}.chat-shell{display:grid;grid-template-columns:370px minmax(0,1fr);height:clamp(620px,calc(100dvh - 225px),850px);min-height:0;border:1px solid #dce2d7;border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 12px 36px rgba(30,52,40,.08)}
.thread-pane{display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;min-width:0;border-right:1px solid #dfe4dc;background:#fff}.thread-toolbar{display:flex;align-items:center;justify-content:space-between;padding:16px 18px;background:#f4f6f1;border-bottom:1px solid #e1e5dd}.thread-toolbar>div{display:flex;flex-direction:column}.thread-toolbar strong{font-size:19px}.thread-toolbar small{font-size:11px}.icon-button{display:inline-grid;place-items:center;width:38px;height:38px;padding:0;border:0;border-radius:50%;background:transparent;color:#385546}.icon-button:hover{background:#e7ece5}.thread-filters{padding:12px;background:#fff;border-bottom:1px solid #e6e9e2}.search-box{display:flex!important;align-items:center;gap:9px;margin:0!important;padding:0 12px;border-radius:9px;background:#f1f3ef;color:#718074}.search-box input{width:100%;padding:10px 0;border:0;background:transparent;outline:0}.filter-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}.select-wrap{position:relative;margin:0!important}.select-wrap select{width:100%;appearance:none;padding-right:28px!important}.select-wrap svg{position:absolute;right:9px;top:50%;transform:translateY(-50%);pointer-events:none}.thread-list{overflow-y:auto;min-height:0}.thread{display:grid;grid-template-columns:48px minmax(0,1fr);gap:12px;width:100%;padding:13px 15px;text-align:left;border:0;border-bottom:1px solid #edf0eb;background:#fff;color:#273a30}.thread:hover,.thread.active{background:#f2f5ef}.thread.active{box-shadow:inset 4px 0 #c89b36}.avatar{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#dfe8dc;color:#315341;font-size:14px;font-weight:800}.avatar.large{width:43px;height:43px;flex:0 0 auto}.thread-copy{min-width:0;display:flex;flex-direction:column;gap:3px}.thread-line{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}.thread-line strong,.preview{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.thread-line time{flex:0 0 auto;font-size:10px;color:#849081}.thread.unread .thread-line time{color:#b38424;font-weight:700}.preview{font-size:12px;color:#768176}.owner{font-size:10px!important}.unread-dot{width:9px;height:9px;border-radius:50%;background:#c89b36;flex:0 0 auto}.pager{display:flex;justify-content:space-between;align-items:center;padding:10px 13px;border-top:1px solid #e5e9e2;font-size:11px}
.conversation-pane{display:grid;grid-template-rows:auto auto auto minmax(0,1fr) auto;min-width:0;min-height:0;background:#eef1e9}.chat-header{display:flex;align-items:center;gap:12px;padding:11px 18px;background:#f4f6f1;border-bottom:1px solid #dfe4dc;min-width:0}.chat-identity{min-width:0;flex:1}.chat-identity h2{margin:0;font-size:16px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chat-identity p{margin:2px 0 0;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chat-actions{justify-content:flex-end;flex-wrap:nowrap}.chat-actions button{padding:8px 11px}.chat-alerts{padding:8px 14px;background:#fff}.chat-alerts p{margin:0}.assignment{padding:8px 18px;background:#fff;border-bottom:1px solid #dfe4dc;font-size:12px}.assignment .grid{margin:7px 0}.messages{min-height:0;overflow-y:auto;padding:24px clamp(16px,5vw,68px);display:flex;flex-direction:column;gap:4px;background-color:#ebece5;background-image:radial-gradient(rgba(67,88,72,.055) 1px,transparent 1px);background-size:18px 18px;scroll-behavior:smooth}.older{align-self:center;margin-bottom:12px;padding:7px 13px;border:1px solid #dce2d7;border-radius:16px;background:#fff;color:#526458;font-size:11px}.bubble-row{display:flex;width:100%}.bubble-row.outbound{justify-content:flex-end}.bubble{position:relative;max-width:min(70%,680px);padding:8px 10px 6px;border:1px solid rgba(44,70,54,.09);border-radius:8px;background:#fff;box-shadow:0 1px 1px rgba(26,44,33,.08);color:#26372e}.bubble-row.outbound .bubble{background:#dcecd5}.bubble p{margin:0;padding-right:54px;white-space:pre-wrap;word-break:break-word;color:#26372e;line-height:1.42;font-size:14px}.bubble audio{display:block;width:min(320px,100%);margin-bottom:7px}.muted{font-style:italic;color:#768176!important}.button-list{margin:8px -10px -2px;border-top:1px solid rgba(61,91,70,.14)}.button-list span{display:block;padding:8px 12px;text-align:center;color:#28705a;border-top:1px solid rgba(61,91,70,.1);font-size:13px}.button-list span:first-child{border-top:0}.chosen{display:block;margin:5px 48px 0 0;color:#28705a;font-size:12px}.bubble-meta{float:right;display:inline-flex;align-items:center;gap:3px;margin:4px 0 0 10px;color:#778379;font-size:9px}.bubble-meta .read{color:#2587a5}.composer{padding:10px 14px;background:#f4f6f1;border-top:1px solid #dfe4dc}.compose-row{display:flex;gap:9px;align-items:flex-end}.composer textarea{min-height:42px;max-height:120px;resize:vertical;padding:11px 14px;border:1px solid #d8ddd5;border-radius:21px;background:#fff;line-height:1.4}.send-button{display:grid;place-items:center;flex:0 0 42px;width:42px;height:42px;padding:0;border:0;border-radius:50%;background:#2d624b;color:#fff}.composer>small{display:block;margin:4px 10px 0;font-size:9px}.composer.locked{display:flex;align-items:center;justify-content:center;gap:8px;min-height:62px;color:#75806b}.template-select{margin:0 0 8px!important}.placeholder{display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;padding:40px;text-align:center;color:#b58a31;background:#f4f6f1}.placeholder h2{margin:18px 0 4px}.placeholder p{max-width:430px}.mobile-back{display:none}
.box{padding:24px;margin:0 0 18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.inbox label:not(.check-label){display:flex;flex-direction:column;gap:7px;font-size:12px;margin:10px 0}.inbox select{padding:9px;border:1px solid #daddd2;background:white;border-radius:9px;max-width:100%}.notice{padding:12px;background:#faf0d4;border-radius:9px}.chat-alerts .notice{display:flex;gap:8px;align-items:center}.empty{padding:25px;text-align:center}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:980px){.chat-shell{grid-template-columns:310px minmax(0,1fr)}.bubble{max-width:82%}.chat-actions button{font-size:11px}}
@media(max-width:720px){.heading{align-items:flex-start}.chat-shell{height:calc(100dvh - 190px);min-height:560px;grid-template-columns:1fr}.chat-shell.selected .thread-pane{display:none}.chat-shell:not(.selected) .conversation-pane{display:none}.thread-pane{border-right:0}.mobile-back{display:inline-grid}.chat-header{padding:9px 10px}.chat-identity p{max-width:52vw}.chat-actions button{padding:7px 8px}.messages{padding:16px 9px}.bubble{max-width:91%}.composer{padding:8px}.heading p{display:none}}
</style>
